('Alice', 'Alice'), ('Bob', 'Bob'), ('Carl', 'Carl'), ('Dan', 'Dan'), ('Eve', 'Eve'),\
('Alice', 'Carl'), ('Carl', 'Alice'), ('Dan', 'Eve'), ('Eve', 'Dan')\
}

We can then compute the set of families:

families = quotient({'Alice', 'Bob', 'Carl', 'Dan', 'Eve'}, R)

